        "That long, detectable, treatable precancerous phase makes cervical cancer the only common cancer of women preventable outright.",
        "A woman screened even **twice in her life** gains a large part of the benefit of annual screening.",
        "Risk factors: **early first intercourse and early marriage, multiple partners or a partner with multiple partners, and high parity**.",
        "Also: **long-term combined oral contraceptive use, smoking, poor genital hygiene, low socio-economic status, and immunosuppression**.",
        "In HIV the risk of invasive disease is **6 times higher**.",
        "The **WHO elimination strategy sets the 90-70-90 targets for 2030**. [WHO 2020]",
        "**90% of girls vaccinated by 15, 70% of women screened with a high-performance test at 35 and 45, 90% with disease treated.** [WHO 2020]",
