        "**Visual inspection with acetic acid (VIA) is the workhorse of the Indian programme** - 5% acetic acid applied and the cervix read in good light after one minute.",
        "A **dense, opaque, well-defined acetowhite lesion touching the squamocolumnar junction within the transformation zone is a positive test**.",
        "Acetic acid coagulates the abundant nuclear protein of dysplastic cells and turns them white.",
        "VIA has a **sensitivity of roughly 60-70% and specificity of about 85%** for CIN2 or worse.",
        "VIA is **cheap, needs no laboratory, and gives an immediate result** - permitting single-visit screen-and-treat.",
        "Single-visit screen-and-treat is the only way to avoid the huge loss to follow-up in Indian programmes.",
        "**VIA is not valid after the menopause** - the squamocolumnar junction recedes into the canal and cannot be seen.",
        "VIA is also unreliable in frank cervicitis and must never be used where a growth or ulcer is visible.",
        "**Cervical cytology (Pap smear or liquid-based) is reported by the Bethesda 2014 system** - NILM, ASC-US, ASC-H, LSIL, HSIL, atypical glandular cells or carcinoma.",
