        "Ask whether coital function is to be preserved - that single answer decides whether **colpocleisis** is an option. [Te Linde 12e]",
        "Chronic discharge or bleeding from the exposed mucosa points to a decubitus ulcer. [Shaw 17e]",
        "History: parity and the detail of each delivery - place, duration, instrumental or not, birth weight, tears and their repair. [Dutta 8e]",
