        "If the findings do not match the symptoms, examine the woman standing. [IUGA/ICS 2016]",
        "Reduce the prolapse and perform a **cough stress test** - to unmask occult stress incontinence. [NICE NG123 2019]",
        "Quantify each compartment - Baden-Walker at minimum, POP-Q if you can. [NICE NG123 2019]",
        "Measure or estimate gh, pb and tvl. [IUGA/ICS 2016]",
