  pearls: [
    "The commonest single error in this question is calling the round ligament a support of the uterus. It maintains anteversion; the broad ligament is a peritoneal fold with no supporting function at all. The true mechanical supports at the cervix are the cardinal (Mackenrodt) and uterosacral ligaments, and the true weight-bearing support is the levator ani.",
    "Say it as an image and it is remembered: the ligaments are the moorings, the levator plate is the berth. When the levator plate sags from horizontal to vertical and the genital hiatus opens, the ligaments take a load they were never built for, stretch, and give way - which is why every prolapse repair must also address the floor and the forces acting on it.",
    "Water under the bridge: the ureter passes beneath the uterine artery about 1.5 to 2 cm lateral to the supravaginal cervix, inside the upper cardinal ligament. That single sentence explains the ureteric injury rate at hysterectomy, why the bladder is pushed up before the uterine pedicle is clamped, and why cystoscopy is advised after high uterosacral suspension.",
    "Hysterectomy is not an operation for prolapse. Removing the uterus removes the organ, not the defect; unless the vault is re-suspended by a McCall culdoplasty, high uterosacral suspension or sacrospinous fixation, vault prolapse follows in roughly one in ten women whose hysterectomy was done for prolapse.",
    "POP-Q stage II is the stage that straddles the hymen, and it is also the stage at which women start to feel the bulge. Symptoms correlate poorly with anatomy above and below that line - treat the woman, not the number.",
    "Reduce the prolapse and ask her to cough before you plan surgery. Advanced prolapse kinks the urethra and hides stress incontinence in a fifth to a third of women, who are then unpleasantly surprised to be wet after a successful repair.",
    "Heal the decubitus ulcer before you operate. A pessary or bed rest with a pack, vaginal oestrogen and treatment of infection heals it in two to three weeks; an ulcer that does not heal, or that has a rolled edge or an indurated base, is biopsied, not repaired.",
    "The ring pessary is the first-line device and suits most women; the shelf or Gellhorn is for advanced descent or a deficient perineum that will not retain a ring. Never fit a pessary without booking the follow-up - the forgotten pessary erodes into bladder or rectum, and that complication is entirely the fitter's responsibility.",
    "Elongation of the cervix is not the same as descent of the uterus. On POP-Q, a difference between points C and D of more than about 4 cm tells you the cervix is long rather than the uterus low, and that is precisely the woman for whom a Manchester repair, not a hysterectomy, is the right operation.",
    "Be precise about mesh. Transvaginal mesh for vaginal wall prolapse is restricted to research by NICE NG123, paused in the United Kingdom since 2018 and off the United States market since 2019. Abdominal sacrocolpopexy mesh is a different question and remains recommended. Saying simply that mesh is banned is wrong and loses the mark.",
  ],
